const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const num=n=>Number(n||0).toLocaleString('pt-BR',{maximumFractionDigits:2});
const dateBR=s=>s?new Date(s+'T12:00:00').toLocaleDateString('pt-BR'):'';
let uidCounter=0;
const issuedIds=new Set();
const uid=(p='ID')=>{
  let id;
  do {
    const randomId=globalThis.crypto?.randomUUID?.();
    id=`${p}-${randomId||`${Date.now().toString(36).toUpperCase()}-${(++uidCounter).toString(36).toUpperCase()}-${Math.random().toString(36).slice(2,10).toUpperCase()}`}`;
  } while(issuedIds.has(id));
  issuedIds.add(id);
  return id;
};
