let db=load(); let route='dashboard';
function load(){return structuredClone(seed)}
function cacheState(){return true;} // Operational state is held in memory and persisted on the server.
function save(msg){cacheState(); if(msg)toast(msg); renderNav();}
function reset(){db=structuredClone(seed);save('Dados de demonstração restaurados');route='dashboard';render()}
function ent(arr,id){return db[arr].find(x=>x.id===id)}
function audit(acao,entidade,detalhe=''){db.audit.unshift({id:uid('LOG'),data:new Date().toISOString(),usuario:window.DIRECTFUEL_CURRENT_USER||'Usuário Vixpar',acao,entidade,detalhe}); if(db.audit.length>300)db.audit.length=300}
function toast(t){const d=document.createElement('div');d.className='toast';d.textContent=t;$('#toast').append(d);setTimeout(()=>d.remove(),2600)}
function badge(s){let c=/ativo|vigente|medido|conciliado|aprovado/i.test(s)?'ok':/pendente|aguardando|atenção|futuro/i.test(s)?'warn':/inativo|cancelado/i.test(s)?'off':'bad';return `<span class="badge ${c}">${s}</span>`}
function val(id){return $('#'+id)?.value?.trim()||''}
function nval(id){return Number(($('#'+id)?.value||'0').replace(',','.'))||0}
function normalizePlate(value){return String(value||'').toUpperCase().replace(/[^A-Z0-9]/g,'')}
function opts(arr,label,id='id'){return db[arr].filter(x=>x.ativo!==false&&x.status!=='Inativo').map(x=>`<option value="${x[id]}">${label(x)}</option>`).join('')}
function distribNome(id){return ent('distribuidores',id)?.nome||'-'}
function baseNome(id){let b=ent('bases',id);return b?`${b.codigo} - ${b.localidade}/${b.uf} - ${distribNome(b.distribuidorId)}`:'-'}
function postoNome(id){return ent('postos',id)?.fantasia||ent('postos',id)?.razao||'-'}
function unidadeNome(id){return ent('unidades',id)?.nome||'-'}
function produtoNome(id){return ent('produtos',id)?.curta||ent('produtos',id)?.descricao||'-'}

const navGroups=[
 ['GERAL',[['dashboard','Dashboard','dashboard']]],
 ['OPERAÇÃO',[['abastecimentos','Abastecimentos','abastecimentos'],['medicoes','Medições','medicoes']]],
 ['COMERCIAL',[['acordos','Acordos & Calculadora','acordos']]],
 ['REDE',[['postos','Postos','postos'],['rede','Rede de Atendimento','rede'],['bases','Bases Supridoras','bases']]],
 ['CADASTROS',[['distribuidoras','Distribuidoras','distribuidoras'],['produtos','Produtos','produtos'],['unidades','Unidades Vixpar','unidades'],['frota','Frota','frota']]],
 ['ANÁLISES',[['analysis_geo','Análise geográfica','dashboard'],['ticketlog_import','Carga Ticketlog','dashboard']]],
 ['GESTÃO',[['relatorios','Relatórios','relatorios'],['documentos','Documentos','documentos']]],
 ['ADMINISTRAÇÃO',[['config','Configurações',null],['audit','Auditoria',null]]]
];
function renderNav(){let h='';for(const[g,items]of navGroups){let visible=items.filter(i=>!i[2]||db.config.modules[i[2]]!==false);if(!visible.length)continue;h+=`<div class="nav-group"><div class="nav-group-title">${g}</div>`+visible.map(i=>`<button class="nav-item ${route===i[0]?'active':''}" data-route="${i[0]}">${i[1]}</button>`).join('')+'</div>'}$('#nav').innerHTML=h;$$('.nav-item').forEach(b=>b.onclick=()=>{route=b.dataset.route;render()})}
function pageTitle(t,s='Gestão de abastecimento'){ $('#pageTitle').textContent=t;$('#pageSub').textContent=s;}
function render(){renderNav();const map={dashboard,postos,bases,distribuidoras,produtos,unidades,frota,rede,acordos,abastecimentos,medicoes,relatorios,documentos,config,audit:auditPage};(route.startsWith("report_")?relatorios:(map[route]||dashboard))()}

function dashboard(){pageTitle('Dashboard','Visão executiva do DirectFuel Vixpar');let abs=db.abastecimentos, vol=abs.reduce((a,x)=>a+x.qt,0),tot=abs.reduce((a,x)=>a+x.total,0),pend=abs.filter(x=>!x.medicaoId),economia=db.acordos.reduce((a,x)=>a+Math.max(0,(x.ticketlog-x.preco))*x.volumeMes,0);let byUnit={};abs.forEach(x=>byUnit[x.unidadeId]=(byUnit[x.unidadeId]||0)+x.qt);let max=Math.max(1,...Object.values(byUnit));$('#view').innerHTML=`
<div class="grid cards"><div class="card"><div class="label">Volume registrado</div><div class="value">${num(vol)} L</div><div class="delta">${abs.length} abastecimentos</div></div><div class="card"><div class="label">Valor abastecido</div><div class="value">${money(tot)}</div><div class="delta">Base demonstrativa</div></div><div class="card"><div class="label">Pendentes de medição</div><div class="value">${pend.length}</div><div class="delta">${num(pend.reduce((a,x)=>a+x.qt,0))} L</div></div><div class="card"><div class="label">Economia potencial x Ticketlog</div><div class="value">${money(economia)}</div><div class="delta">Projeção mensal dos acordos</div></div></div>
<div class="split"><div class="panel"><h2>Volume por unidade</h2>${Object.entries(byUnit).map(([u,v])=>`<div style="margin:14px 0"><div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:6px"><span>${unidadeNome(u)}</span><strong>${num(v)} L</strong></div><div class="chartbar"><span style="width:${v/max*100}%"></span></div></div>`).join('')||'<p class="muted">Sem dados.</p>'}</div>
<div class="panel"><h2>Pendências e alertas</h2><div class="kpi-list"><div class="mini"><span class="muted">Acordos vigentes</span><strong>${db.acordos.filter(x=>window.DirectFuelImportRules.effectiveAgreementStatus(x)==='Vigente').length}</strong></div><div class="mini"><span class="muted">Medições</span><strong>${db.medicoes.length}</strong></div><div class="mini"><span class="muted">Postos ativos</span><strong>${db.postos.filter(x=>x.status==='Ativo').length}</strong></div><div class="mini"><span class="muted">Divergências de preço</span><strong>${abs.filter(x=>{let a=window.DirectFuelImportRules.findAgreement(db.acordos,x.postoId,x.produtoId,x.data);return a&&Math.abs(x.preco-a.preco)>.001}).length}</strong></div></div></div></div>`}

function genericPage(cfg){pageTitle(cfg.title,cfg.sub||'Cadastro mestre');let rows=db[cfg.arr];$('#view').innerHTML=`<div class="panel"><div class="toolbar"><button class="btn primary" id="newRec">+ Novo</button></div><div class="table-wrap"><table><thead><tr>${cfg.cols.map(c=>`<th>${c[0]}</th>`).join('')}<th>Ações</th></tr></thead><tbody>${rows.map(r=>`<tr>${cfg.cols.map(c=>`<td>${typeof c[1]==='function'?c[1](r):(r[c[1]]??'')}</td>`).join('')}<td><button class="btn small secondary edit" data-id="${r.id}">Editar</button> <button class="btn small danger del" data-id="${r.id}">Excluir</button></td></tr>`).join('')||`<tr><td colspan="${cfg.cols.length+1}" class="muted">Nenhum registro.</td></tr>`}</tbody></table></div></div>`;$('#newRec').onclick=()=>cfg.form();$$('.edit').forEach(b=>b.onclick=()=>cfg.form(ent(cfg.arr,b.dataset.id)));$$('.del').forEach(b=>b.onclick=()=>{if(confirm('Excluir este registro?')){db[cfg.arr]=db[cfg.arr].filter(x=>x.id!==b.dataset.id);audit('Exclusão',cfg.title,b.dataset.id);save('Registro excluído');render()}})}
function modal(title,body,onSave){let back=document.createElement('div');back.className='modal-back';back.innerHTML=`<div class="modal"><h3>${title}</h3>${body}<div class="modal-actions"><button class="btn secondary cancel">Cancelar</button><button class="btn primary save">Salvar</button></div></div>`;document.body.append(back);$('.cancel',back).onclick=()=>back.remove();$('.save',back).onclick=()=>onSave(back)}
function upsert(arr,obj,key='id'){let i=db[arr].findIndex(x=>x[key]===obj[key]);if(i>=0)db[arr][i]=obj;else db[arr].push(obj);audit(i>=0?'Alteração':'Inclusão',arr,obj[key]);save('Registro salvo');render()}
function nextPostCode(){let max=Math.max(0,...(db.postos||[]).map(x=>Number(String(x.codigo||'').match(/(\d+)$/)?.[1]||0)));return `PST-${String(max+1).padStart(4,'0')}`}

function distribuidoras(){genericPage({title:'Distribuidoras',arr:'distribuidores',cols:[['Código','codigo'],['Distribuidora','nome'],['Status',x=>badge(x.ativo?'Ativa':'Inativa')]],form:r=>modal(r?'Editar distribuidora':'Nova distribuidora',`<div class="form-grid two"><div class="field"><label>Nome</label><input id="fNome" value="${r?.nome||''}"></div><div class="field"><label>Código interno</label><input id="fCodigo" value="${r?.codigo||''}"></div><div class="field"><label>Status</label><select id="fAtivo"><option value="1" ${r?.ativo!==false?'selected':''}>Ativa</option><option value="0" ${r?.ativo===false?'selected':''}>Inativa</option></select></div><div class="field"><label>Observação</label><input id="fObs" value="${r?.obs||''}"></div></div>`,m=>{if(!val('fNome'))return toast('Informe o nome');upsert('distribuidores',{id:r?.id||uid('D'),nome:val('fNome'),codigo:val('fCodigo'),ativo:val('fAtivo')==='1',obs:val('fObs')});m.remove()})})}
function bases(){genericPage({title:'Bases Supridoras',arr:'bases',cols:[['Código','codigo'],['Localidade',x=>`${x.localidade}/${x.uf}`],['Distribuidora',x=>distribNome(x.distribuidorId)],['Status',x=>badge(x.ativo?'Ativa':'Inativa')]],form:r=>modal(r?'Editar base':'Nova base',`<div class="form-grid"><div class="field"><label>Código Base</label><input id="fCodigo" value="${r?.codigo||''}"></div><div class="field"><label>Localidade</label><input id="fLocal" value="${r?.localidade||''}"></div><div class="field"><label>UF</label><input id="fUf" maxlength="2" value="${r?.uf||''}"></div><div class="field"><label>Distribuidora</label><select id="fDist">${opts('distribuidores',x=>x.nome)}</select></div><div class="field"><label>Status</label><select id="fAtivo"><option value="1">Ativa</option><option value="0">Inativa</option></select></div></div>`,m=>{if(!val('fCodigo')||!val('fLocal'))return toast('Preencha código e localidade');upsert('bases',{id:r?.id||uid('B'),codigo:val('fCodigo'),localidade:val('fLocal'),uf:val('fUf').toUpperCase(),distribuidorId:val('fDist'),ativo:val('fAtivo')==='1'});m.remove()})})}
function produtos(){genericPage({title:'Produtos',arr:'produtos',cols:[['Produto','descricao'],['Unidade','unidade'],['Código SAP','sap'],['Status',x=>badge(x.ativo?'Ativo':'Inativo')]],form:r=>modal(r?'Editar produto':'Novo produto',`<div class="form-grid"><div class="field"><label>Descrição</label><input id="fDesc" value="${r?.descricao||''}"></div><div class="field"><label>Descrição curta</label><input id="fCurta" value="${r?.curta||''}"></div><div class="field"><label>Família</label><input id="fFam" value="${r?.familia||'Diesel'}"></div><div class="field"><label>Unidade</label><input id="fUn" value="${r?.unidade||'L'}"></div><div class="field"><label>Código SAP</label><input id="fSap" value="${r?.sap||''}"></div><div class="field"><label>Status</label><select id="fAtivo"><option value="1">Ativo</option><option value="0">Inativo</option></select></div></div>`,m=>{if(!val('fDesc')||(db.config.required.produtoSap&&!val('fSap')))return toast('Preencha os campos obrigatórios');upsert('produtos',{id:r?.id||uid('P'),descricao:val('fDesc'),curta:val('fCurta')||val('fDesc'),familia:val('fFam'),unidade:val('fUn'),sap:val('fSap'),ativo:val('fAtivo')==='1'});m.remove()})})}
function unidades(){genericPage({title:'Unidades Vixpar',arr:'unidades',cols:[['Unidade','nome'],['Centro SAP','centroSap'],['Depósito SAP',x=>String(x.depositoSap||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))],['Município/UF',x=>`${x.municipio}/${x.uf}`],['Centro de Custo','centroCusto'],['Status',x=>badge(x.ativo?'Ativa':'Inativa')]],form:r=>modal(r?'Editar unidade':'Nova unidade',`<div class="form-grid"><div class="field"><label>Nome Unidade</label><input id="fNome" value="${r?.nome||''}"></div><div class="field"><label>Razão Social faturamento</label><input id="fRazao" value="${r?.razao||''}"></div><div class="field"><label>CNPJ</label><input id="fCnpj" value="${r?.cnpj||''}"></div><div class="field"><label>Centro SAP</label><input id="fCentro" value="${r?.centroSap||''}"></div><div class="field"><label for="fDepositoSap">Depósito SAP</label><input id="fDepositoSap" type="text" value="${String(r?.depositoSap||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}"></div><div class="field"><label>Município</label><input id="fMun" value="${r?.municipio||''}"></div><div class="field"><label>UF</label><input id="fUf" maxlength="2" value="${r?.uf||''}"></div><div class="field"><label>Centro de Custo padrão</label><input id="fCc" value="${r?.centroCusto||''}"></div><div class="field"><label>Status</label><select id="fAtivo"><option value="1">Ativa</option><option value="0">Inativa</option></select></div></div>`,m=>{if(!val('fNome')||!val('fCentro'))return toast('Informe unidade e Centro SAP');upsert('unidades',{id:r?.id||uid('U'),nome:val('fNome'),razao:val('fRazao'),cnpj:val('fCnpj'),centroSap:val('fCentro'),depositoSap:val('fDepositoSap').trim(),municipio:val('fMun'),uf:val('fUf').toUpperCase(),centroCusto:val('fCc'),ativo:val('fAtivo')==='1'});m.remove()})})}
function postos(){
  genericPage({title:'Postos',arr:'postos',cols:[
    ['ID',x=>x.codigo||x.id],['Posto',x=>`<strong>${x.fantasia||x.razao}</strong><br><span class="muted">${x.razao}</span>`],['CNPJ','cnpj'],['Município/UF',x=>`${x.municipio}/${x.uf}`],['Bandeira','bandeira'],['Base padrão',x=>baseNome(x.baseId)],['Distância',x=>`${x.distancia||0} km`],['Georreferência',x=>Number(x.latitude)&&Number(x.longitude)?badge('Georreferenciado'):badge('Pendente')],['Status',x=>badge(x.status)]
  ],form:r=>{
    modal(r?'Editar posto':'Novo posto',`<div class="section-title">Identificação</div><div class="form-grid"><div class="field"><label>ID automático do posto</label><input value="${r?.codigo||r?.id||nextPostCode()}" disabled></div><div class="field"><label>Razão Social</label><input id="fRazao" value="${r?.razao||''}"></div><div class="field"><label>Nome Fantasia</label><input id="fFant" value="${r?.fantasia||''}"></div><div class="field"><label>CNPJ</label><input id="fCnpj" value="${r?.cnpj||''}"></div><div class="field"><label>Nomes do posto na Gekon (um por linha)</label><textarea id="fGekonNames">${(r?.gekonNames||[]).join('\n').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</textarea></div><div class="field"><label>Inscrição Estadual</label><input id="fIe" value="${r?.ie||''}"></div><div class="field"><label>Endereço</label><input id="fEnd" value="${r?.endereco||''}"></div><div class="field"><label>Bairro</label><input id="fBairro" value="${r?.bairro||''}"></div><div class="field"><label>Município</label><input id="fMun" value="${r?.municipio||''}"></div><div class="field"><label>UF</label><input id="fUf" maxlength="2" value="${r?.uf||''}"></div><div class="field"><label>CEP</label><input id="fCep" value="${r?.cep||''}"></div><div class="field"><label>Latitude</label><input type="number" step=".000001" id="fLat" value="${r?.latitude||''}"></div><div class="field"><label>Longitude</label><input type="number" step=".000001" id="fLng" value="${r?.longitude||''}"></div><div class="field"><label>Bandeira</label><input id="fBand" value="${r?.bandeira||''}"></div><div class="field"><label>Código SAP fornecedor</label><input id="fSap" value="${r?.sap||''}"></div><div class="field"><label>Base Supridora padrão</label><select id="fBase">${opts('bases',x=>baseNome(x.id))}</select></div><div class="field"><label>Distância rodoviária (km)</label><input type="number" id="fDist" value="${r?.distancia||0}"></div><div class="field"><label>Status</label><select id="fStatus"><option>Ativo</option><option>Bloqueado</option><option>Inativo</option></select></div></div><div class="section-title">Contato Comercial</div><div class="form-grid"><div class="field"><label>Nome</label><input id="fCcNome" value="${r?.contComercial||''}"></div><div class="field"><label>Telefone</label><input id="fCcTel" value="${r?.telComercial||''}"></div><div class="field"><label>E-mail</label><input id="fCcMail" value="${r?.emailComercial||''}"></div></div><div class="section-title">Contato Financeiro</div><div class="form-grid"><div class="field"><label>Nome</label><input id="fCfNome" value="${r?.contFinanceiro||''}"></div><div class="field"><label>Telefone</label><input id="fCfTel" value="${r?.telFinanceiro||''}"></div><div class="field"><label>E-mail</label><input id="fCfMail" value="${r?.emailFinanceiro||''}"></div></div>`,m=>{
      if(!val('fRazao')||(db.config.required.postoCnpj&&!val('fCnpj'))||(db.config.required.postoMunicipio&&!val('fMun')))return toast('Preencha os campos obrigatórios');
      const gekonNames=[...new Set(val('fGekonNames').split(/\\n|\n/).map(v=>v.trim()).filter(Boolean))];
      if(db.postos.some(p=>p.id!==r?.id&&(p.gekonNames||[]).some(n=>gekonNames.some(v=>window.DirectFuelImportRules.text(v)===window.DirectFuelImportRules.text(n)))))return toast('Nome Gekon já vinculado a outro posto');
      upsert('postos',{gekonNames,id:r?.id||uid('S'),codigo:r?.codigo||nextPostCode(),razao:val('fRazao'),fantasia:val('fFant'),cnpj:val('fCnpj'),ie:val('fIe'),endereco:val('fEnd'),bairro:val('fBairro'),municipio:val('fMun'),uf:val('fUf').toUpperCase(),cep:val('fCep'),latitude:nval('fLat'),longitude:nval('fLng'),geocodeStatus:nval('fLat')&&nval('fLng')?'Georreferenciado':(r?.geocodeStatus||'Pendente'),geocodeUpdatedAt:r?.geocodeUpdatedAt||'',geocodeUpdatedBy:r?.geocodeUpdatedBy||'',bandeira:val('fBand'),sap:val('fSap'),baseId:val('fBase'),distancia:nval('fDist'),status:val('fStatus'),contComercial:val('fCcNome'),telComercial:val('fCcTel'),emailComercial:val('fCcMail'),contFinanceiro:val('fCfNome'),telFinanceiro:val('fCfTel'),emailFinanceiro:val('fCfMail')});m.remove();
    });
    setTimeout(()=>{if(r){$('#fBase').value=r.baseId||'';$('#fStatus').value=r.status||'Ativo'}},0);
  }});
}
function frota(){
  genericPage({title:'Frota',arr:'frota',cols:[['Placa','placa'],['Modelo','modelo'],['Unidade',x=>unidadeNome(x.unidadeId)],['Centro de Custo','centroCusto'],['Produto',x=>produtoNome(x.produtoId)],['Cap. tanque',x=>`${x.capTanque||0} L`],['Status',x=>badge(x.ativo?'Ativo':'Inativo')]],form:r=>{
    modal(r?'Editar veículo':'Novo veículo',`<div class="form-grid"><div class="field"><label>Placa</label><input id="fPlaca" maxlength="8" autocomplete="off" value="${r?.placa||''}"><span class="muted">A placa é a chave única do veículo.</span></div><div class="field"><label>Prefixo</label><input id="fPrefixo" value="${r?.prefixo||''}"></div><div class="field"><label>Fabricante</label><input id="fFab" value="${r?.fabricante||''}"></div><div class="field"><label>Modelo</label><input id="fModelo" value="${r?.modelo||''}"></div><div class="field"><label>Unidade Vixpar</label><select id="fUnid">${opts('unidades',x=>x.nome)}</select></div><div class="field"><label>Centro de Custo</label><input id="fCc" value="${r?.centroCusto||''}"></div><div class="field"><label>Tipo</label><input id="fTipo" value="${r?.tipo||''}"></div><div class="field"><label>Capacidade tanque (L)</label><input type="number" id="fCap" value="${r?.capTanque||0}"></div><div class="field"><label>Produto permitido</label><select id="fProd">${opts('produtos',x=>x.curta)}</select></div><div class="field"><label>Status</label><select id="fAtivo"><option value="1">Ativo</option><option value="0">Inativo</option></select></div></div>`,m=>{
      const placa=normalizePlate(val('fPlaca'));
      if(!placa||!val('fModelo')||(db.config.required.frotaCentroCusto&&!val('fCc')))return toast('Preencha os campos obrigatórios');
      if(!/^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$/.test(placa))return toast('Informe uma placa válida, por exemplo ABC1D23 ou ABC1234');
      if(db.frota.some(x=>x.id!==r?.id&&normalizePlate(x.placa)===placa))return toast(`A placa ${placa} já está cadastrada na frota`);
      upsert('frota',{id:r?.id||uid('F'),placa,prefixo:val('fPrefixo'),fabricante:val('fFab'),modelo:val('fModelo'),unidadeId:val('fUnid'),centroCusto:val('fCc'),tipo:val('fTipo'),capTanque:nval('fCap'),produtoId:val('fProd'),ativo:val('fAtivo')==='1'});m.remove();
    });
    setTimeout(()=>{if(r){$('#fUnid').value=r.unidadeId;$('#fProd').value=r.produtoId;$('#fAtivo').value=r.ativo?'1':'0'}},0);
  }});
}
function rede(){
  genericPage({title:'Rede de Atendimento',sub:'Vínculo Posto × Unidade × Produto × Base',arr:'rede',cols:[['Posto',x=>postoNome(x.postoId)],['Unidade',x=>unidadeNome(x.unidadeId)],['Produto',x=>produtoNome(x.produtoId)],['Base',x=>baseNome(x.baseId)],['Status',x=>badge(x.ativo?'Ativo':'Inativo')]],form:r=>{
    modal(r?'Editar vínculo':'Novo vínculo',`<div class="form-grid two"><div class="field"><label>Posto</label><select id="fPosto">${opts('postos',x=>x.fantasia||x.razao)}</select></div><div class="field"><label>Unidade Vixpar</label><select id="fUnid">${opts('unidades',x=>x.nome)}</select></div><div class="field"><label>Produto</label><select id="fProd">${opts('produtos',x=>x.curta)}</select></div><div class="field"><label>Base supridora</label><select id="fBase">${opts('bases',x=>baseNome(x.id))}</select></div><div class="field"><label>Status</label><select id="fAtivo"><option value="1">Ativo</option><option value="0">Inativo</option></select></div></div>`,m=>{upsert('rede',{id:r?.id||uid('R'),postoId:val('fPosto'),unidadeId:val('fUnid'),produtoId:val('fProd'),baseId:val('fBase'),ativo:val('fAtivo')==='1'});m.remove()});
    setTimeout(()=>{if(r){$('#fPosto').value=r.postoId;$('#fUnid').value=r.unidadeId;$('#fProd').value=r.produtoId;$('#fBase').value=r.baseId;$('#fAtivo').value=r.ativo?'1':'0'}},0);
  }});
}
function acordos(){pageTitle('Acordos & Calculadora','Negociação, vigência e memória de cálculo');$('#view').innerHTML=`<div class="panel"><div class="toolbar"><button class="btn primary" id="newAcordo">+ Novo acordo</button></div><div class="table-wrap"><table><thead><tr><th>Número</th><th>Posto</th><th>Unidade</th><th>Produto</th><th>Preço</th><th>PRV</th><th>Ticketlog</th><th>Δ PRV</th><th>Vigência</th><th>Status</th><th>Ações</th></tr></thead><tbody>${db.acordos.map(a=>`<tr><td>${a.numero}</td><td>${postoNome(a.postoId)}</td><td>${unidadeNome(a.unidadeId)}</td><td>${produtoNome(a.produtoId)}</td><td>${money(a.preco)}</td><td>${money(a.prv)}</td><td>${money(a.ticketlog)}</td><td class="${a.preco<=a.prv?'price-good':'price-bad'}">${money(a.preco-a.prv)}</td><td>${dateBR(a.inicio)} a ${dateBR(a.fim)}</td><td>${badge(window.DirectFuelImportRules.effectiveAgreementStatus(a))}</td><td><button class="btn small secondary editA" data-id="${a.id}">Editar</button> <button class="btn small secondary printA" data-id="${a.id}">Ficha</button></td></tr>`).join('')}</tbody></table></div></div>`;$('#newAcordo').onclick=()=>formAcordo();$$('.editA').forEach(b=>b.onclick=()=>formAcordo(ent('acordos',b.dataset.id)));$$('.printA').forEach(b=>b.onclick=()=>printAgreement(ent('acordos',b.dataset.id)))}
function formAcordo(r){modal(r?'Editar acordo':'Novo acordo',`<div class="form-grid"><div class="field"><label>Número</label><input id="aNumero" value="${r?.numero||('AC-'+new Date().getFullYear()+'-'+String(db.acordos.length+1).padStart(3,'0'))}"></div><div class="field"><label>Posto</label><select id="aPosto">${opts('postos',x=>x.fantasia||x.razao)}</select></div><div class="field"><label>Unidade</label><select id="aUnid">${opts('unidades',x=>x.nome)}</select></div><div class="field"><label>Produto</label><select id="aProd">${opts('produtos',x=>x.curta)}</select></div><div class="field"><label>Base supridora</label><select id="aBase">${opts('bases',x=>baseNome(x.id))}</select></div><div class="field"><label>Responsável análise</label><input id="aResp" value="${r?.responsavel||''}"></div><div class="field"><label>Início vigência</label><input type="date" id="aInicio" value="${r?.inicio||new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Fim vigência</label><input type="date" id="aFim" value="${r?.fim||''}"></div><div class="field"><label>Status</label><select id="aStatus"><option>Vigente</option><option>Encerrado</option><option>Cancelado</option></select></div></div><div class="section-title">Calculadora de preço líquido</div><div class="form-grid"><div class="field"><label>FOB à vista / Paramétrica Vixpar</label><input type="number" step="0.0001" id="aFob" value="${r?.fob??5.45}"></div><div class="field"><label>Custo Frete / L</label><input type="number" step="0.0001" id="aFrete" value="${r?.frete??0.18}"></div><div class="field"><label>Taxa financeira Vixpar (% a.m.)</label><input type="number" step="0.01" id="aTaxaFin" value="${r?.taxaFin??db.config.params.taxaFinanceira}"></div><div class="field"><label>Prazo pagamento (dias)</label><input type="number" id="aPag" value="${r?.pagamento??db.config.params.pagDirectFuel}"></div><div class="field"><label>Margem Posto (%)</label><input type="number" step="0.01" id="aMargem" value="${r?.margem??db.config.params.margemPosto}"></div><div class="field"><label>Taxa adm (%)</label><input type="number" step="0.01" id="aAdm" value="${r?.taxaAdm??db.config.params.taxaAdm}"></div><div class="field"><label>Ciclo medição (dias)</label><input type="number" id="aCiclo" value="${r?.ciclo??db.config.params.cicloDirectFuel}"></div><div class="field"><label>Preço negociado</label><input type="number" step="0.0001" id="aPreco" value="${r?.preco||0}"></div><div class="field"><label>Preço Ticketlog</label><input type="number" step="0.0001" id="aTicket" value="${r?.ticketlog||0}"></div><div class="field"><label>Volume estimado mês (L)</label><input type="number" id="aVol" value="${r?.volumeMes||0}"></div></div><div class="panel" style="margin-top:14px;box-shadow:none"><div class="kpi-list"><div class="mini"><span class="muted">CIF à vista</span><strong id="kCif">-</strong></div><div class="mini"><span class="muted">Custo financeiro</span><strong id="kFin">-</strong></div><div class="mini"><span class="muted">Preço alvo calculado</span><strong id="kAlvo">-</strong></div><div class="mini"><span class="muted">Impacto mensal vs Ticketlog</span><strong id="kEco">-</strong></div></div></div><div class="field"><label>Observações</label><textarea id="aObs">${r?.obs||''}</textarea></div>`,m=>{let c=calcA();if(!val('aNumero')||!val('aPosto')||!val('aProd')||!val('aPreco'))return toast('Preencha número, posto, produto e preço negociado');upsert('acordos',{id:r?.id||uid('A'),numero:val('aNumero'),postoId:val('aPosto'),unidadeId:val('aUnid'),produtoId:val('aProd'),baseId:val('aBase'),inicio:val('aInicio'),fim:val('aFim'),preco:nval('aPreco'),prv:c.alvo,ticketlog:nval('aTicket'),fob:nval('aFob'),frete:nval('aFrete'),margem:nval('aMargem'),taxaAdm:nval('aAdm'),taxaFin:nval('aTaxaFin'),ciclo:nval('aCiclo'),pagamento:nval('aPag'),volumeMes:nval('aVol'),status:val('aStatus'),responsavel:val('aResp'),obs:val('aObs')});m.remove()});setTimeout(()=>{if(r){$('#aPosto').value=r.postoId;$('#aUnid').value=r.unidadeId;$('#aProd').value=r.produtoId;$('#aBase').value=r.baseId;$('#aStatus').value=r.status}['aFob','aFrete','aTaxaFin','aPag','aMargem','aAdm','aPreco','aTicket','aVol'].forEach(id=>$('#'+id).addEventListener('input',calcA));calcA()},0)}
function calcA(){let fob=nval('aFob'),frete=nval('aFrete'),taxa=nval('aTaxaFin')/100,pag=nval('aPag'),marg=nval('aMargem')/100,adm=nval('aAdm')/100,cif=fob+frete,fin=cif*taxa*(pag/30),base=cif+fin,alvo=base*(1+marg)*(1+adm),preco=nval('aPreco'),tick=nval('aTicket'),vol=nval('aVol'),eco=(tick-preco)*vol;if($('#kCif')){$('#kCif').textContent=money(cif);$('#kFin').textContent=money(fin);$('#kAlvo').textContent=money(alvo);$('#kEco').textContent=money(eco)}return{cif,fin,alvo}}
function printAgreement(a){let w=window.open('','_blank');w.document.write(`<html><head><title>Ficha ${a.numero}</title><style>body{font-family:Arial;padding:30px;color:#17212b}.h{border-bottom:3px solid #0f5a47;padding-bottom:12px;margin-bottom:20px}h1{margin:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.box{border:1px solid #ddd;padding:12px;border-radius:8px}.big{font-size:26px;font-weight:bold}.sign{margin-top:70px;display:grid;grid-template-columns:1fr 1fr;gap:50px}.line{border-top:1px solid #333;text-align:center;padding-top:5px}@media print{button{display:none}}</style></head><body><div class="h"><h1>DirectFuel Vixpar</h1><div>Ficha de Aprovação Comercial • ${a.numero}</div></div><div class="grid"><div class="box"><b>Posto</b><br>${postoNome(a.postoId)}</div><div class="box"><b>Unidade</b><br>${unidadeNome(a.unidadeId)}</div><div class="box"><b>Produto</b><br>${produtoNome(a.produtoId)}</div><div class="box"><b>Vigência</b><br>${dateBR(a.inicio)} a ${dateBR(a.fim)}</div><div class="box"><b>Preço negociado</b><div class="big">${money(a.preco)}/L</div></div><div class="box"><b>Preço Referencial Vixpar</b><div class="big">${money(a.prv)}/L</div></div><div class="box"><b>Ticketlog</b><br>${money(a.ticketlog)}/L</div><div class="box"><b>Condições</b><br>Medição: ${a.ciclo} dias • Pagamento: ${a.pagamento} dias • ${a.condicaoPagamento||'Boleto'}</div><div class="box"><b>Margem posto</b><br>${num(a.margem)}%</div><div class="box"><b>Taxa administrativa</b><br>${num(a.taxaAdm)}%</div></div><p><b>Responsável pela análise:</b> ${a.responsavel||'-'}</p><p><b>Observações:</b> ${a.obs||'-'}</p><div class="sign"><div class="line">Suprimentos</div><div class="line">Aprovação</div></div><br><button onclick="print()">Imprimir / Salvar PDF</button></body></html>`);w.document.close()}

function abastecimentos(){pageTitle('Abastecimentos','Carga operacional e validações');$('#view').innerHTML=`<div class="panel"><div class="toolbar"><button class="btn primary" id="newAb">+ Novo abastecimento</button><label class="btn secondary">Importar CSV<input id="csvAb" type="file" accept=".csv" hidden></label></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Data</th><th>Hora</th><th>Posto</th><th>Placa</th><th>Produto</th><th>Odômetro</th><th>Motorista</th><th>Qt</th><th>Preço</th><th>Total</th><th>Filial</th><th>Medição</th><th>Validação</th></tr></thead><tbody>${db.abastecimentos.map(a=>{let ac=window.DirectFuelImportRules.findAgreement(db.acordos,a.postoId,a.produtoId,a.data),f=db.frota.find(x=>x.placa===a.placa),probs=[];if(ac&&Math.abs(a.preco-ac.preco)>.001)probs.push('Preço');if(f&&a.qt>f.capTanque)probs.push('Volume');if(!db.rede.some(r=>r.postoId===a.postoId&&r.unidadeId===a.unidadeId&&r.produtoId===a.produtoId&&r.ativo))probs.push('Rede');return `<tr><td>${a.id}</td><td>${dateBR(a.data)}</td><td>${a.hora}</td><td>${postoNome(a.postoId)}</td><td>${a.placa}</td><td>${produtoNome(a.produtoId)}</td><td>${num(a.odometro)}</td><td>${a.motorista}</td><td>${num(a.qt)} L</td><td>${money(a.preco)}</td><td>${money(a.total)}</td><td>${unidadeNome(a.unidadeId)}</td><td>${a.medicaoId?badge('Medido'):badge('Pendente')}</td><td>${probs.length?badge(probs.join(', ')):badge('OK')}</td></tr>`}).join('')}</tbody></table></div></div>`;$('#newAb').onclick=()=>formAb();$('#csvAb').onchange=importCSV}
function formAb(){modal('Novo abastecimento',`<div class="form-grid"><div class="field"><label>Data</label><input type="date" id="bData" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Hora</label><input type="time" id="bHora"></div><div class="field"><label>Posto</label><select id="bPosto">${opts('postos',x=>x.fantasia||x.razao)}</select></div><div class="field"><label>Placa</label><select id="bPlaca">${opts('frota',x=>`${x.placa} - ${x.modelo}`,'placa')}</select></div><div class="field"><label>Produto</label><select id="bProd">${opts('produtos',x=>x.curta)}</select></div><div class="field"><label>Odômetro</label><input type="number" id="bOdo"></div><div class="field"><label>Motorista</label><input id="bMot"></div><div class="field"><label>Quantidade (L)</label><input type="number" step="0.01" id="bQt"></div><div class="field"><label>Preço unitário</label><input type="number" step="0.0001" id="bPreco"></div><div class="field"><label>Unidade Vixpar</label><select id="bUnid">${opts('unidades',x=>x.nome)}</select></div><div class="field"><label>Centro de Custo</label><input id="bCc"></div><div class="field"><label>Origem</label><select id="bOrig"><option>DirectFuel</option><option>Ticketlog</option><option>Manual</option></select></div></div>`,m=>{let placa=val('bPlaca'),f=db.frota.find(x=>x.placa===placa),qt=nval('bQt'),pre=nval('bPreco');if(!val('bData')||!placa||!qt||!pre)return toast('Preencha data, placa, quantidade e preço');db.abastecimentos.push({id:uid('AB'),data:val('bData'),hora:val('bHora'),postoId:val('bPosto'),placa,veiculo:f?.modelo||'',odometro:nval('bOdo'),motorista:val('bMot'),produtoId:val('bProd'),qt,preco:pre,total:qt*pre,unidadeId:val('bUnid'),centroCusto:val('bCc'),origem:val('bOrig'),medicaoId:null});audit('Inclusão','Abastecimento',placa);save('Abastecimento registrado');m.remove();render()});setTimeout(()=>{$('#bPlaca').onchange=()=>{let f=db.frota.find(x=>x.placa===$('#bPlaca').value);if(f){$('#bUnid').value=f.unidadeId;$('#bCc').value=f.centroCusto;$('#bProd').value=f.produtoId}};$('#bPlaca').onchange()},0)}
function importCSV(e){let f=e.target.files[0];if(!f)return;let rd=new FileReader();rd.onload=()=>{let lines=rd.result.trim().split(/\r?\n/),head=lines.shift().split(';').map(x=>x.trim().toLowerCase());let added=0;for(let l of lines){let p=l.split(';'),o={};head.forEach((h,i)=>o[h]=p[i]);let posto=db.postos.find(x=>x.fantasia===o.posto||x.razao===o.posto),prod=db.produtos.find(x=>x.curta===o.produto||x.descricao===o.produto),un=db.unidades.find(x=>x.nome===o.filial),fro=db.frota.find(x=>x.placa===o.placa);if(!posto||!prod||!un)continue;let qt=Number((o.qt||o.quantidade||'0').replace(',','.')),pre=Number((o.preco||'0').replace(',','.'));db.abastecimentos.push({id:o.id||uid('AB'),data:o.data,hora:o.hora||'',postoId:posto.id,placa:o.placa,veiculo:fro?.modelo||'',odometro:Number(o.odometro||0),motorista:o.motorista||'',produtoId:prod.id,qt,preco:pre,total:qt*pre,unidadeId:un.id,centroCusto:fro?.centroCusto||'',origem:'CSV',medicaoId:null});added++}audit('Importação','Abastecimentos',`${added} registros`);save(`${added} abastecimentos importados`);render()};rd.readAsText(f,'UTF-8')}

function medicoes(){pageTitle('Medições','Vincule abastecimentos à nota fiscal do posto');let pend=db.abastecimentos.filter(x=>!x.medicaoId);$('#view').innerHTML=`<div class="panel"><div class="toolbar"><label>De <input type="date" id="mDe" class="btn secondary"></label><label>Até <input type="date" id="mAte" class="btn secondary"></label><select id="mPosto" class="btn secondary"><option value="">Todos os postos</option>${opts('postos',x=>x.fantasia||x.razao)}</select><button class="btn secondary" id="filtrarM">Filtrar</button><button class="btn primary" id="criarM">Criar medição com selecionados</button></div><div id="pendTable"></div></div><div class="panel"><h2>Medições realizadas / em andamento</h2><div class="table-wrap"><table><thead><tr><th>Medição</th><th>Posto</th><th>Período</th><th>NF</th><th>Qt abastecida</th><th>Valor</th><th>Status</th><th>DANFE</th></tr></thead><tbody>${db.medicoes.map(m=>`<tr><td>${m.numero}</td><td>${postoNome(m.postoId)}</td><td>${dateBR(m.inicio)} a ${dateBR(m.fim)}</td><td>${m.nf||'-'}</td><td>${num(m.qt)} L</td><td>${money(m.valor)}</td><td>${badge(m.status)}</td><td>${m.danfeNome||'-'}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">Nenhuma medição criada.</td></tr>'}</tbody></table></div></div>`;function draw(){let arr=pend.filter(x=>(!val('mDe')||x.data>=val('mDe'))&&(!val('mAte')||x.data<=val('mAte'))&&(!val('mPosto')||x.postoId===val('mPosto')));$('#pendTable').innerHTML=`<div class="table-wrap"><table><thead><tr><th class="checkcell"><input type="checkbox" id="selAll"></th><th>Data</th><th>Posto</th><th>Placa</th><th>Produto</th><th>Filial</th><th>Qt</th><th>Valor</th></tr></thead><tbody>${arr.map(a=>`<tr><td><input type="checkbox" class="selM" value="${a.id}"></td><td>${dateBR(a.data)}</td><td>${postoNome(a.postoId)}</td><td>${a.placa}</td><td>${produtoNome(a.produtoId)}</td><td>${unidadeNome(a.unidadeId)}</td><td>${num(a.qt)} L</td><td>${money(a.total)}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">Nenhum abastecimento pendente para o filtro.</td></tr>'}</tbody></table></div>`;if($('#selAll'))$('#selAll').onchange=e=>$$('.selM').forEach(c=>c.checked=e.target.checked)}draw();$('#filtrarM').onclick=draw;$('#criarM').onclick=()=>{let ids=$$('.selM:checked').map(x=>x.value);if(!ids.length)return toast('Selecione ao menos um abastecimento');formMedicao(ids)}}
function formMedicao(ids){let itens=db.abastecimentos.filter(x=>ids.includes(x.id)),postos=[...new Set(itens.map(x=>x.postoId))],unis=[...new Set(itens.map(x=>x.unidadeId))],prods=[...new Set(itens.map(x=>x.produtoId))];if(postos.length>1)return toast('Uma medição deve conter apenas um posto');let qt=itens.reduce((a,x)=>a+x.qt,0),valor=itens.reduce((a,x)=>a+x.total,0),datas=itens.map(x=>x.data).sort();modal('Criar medição',`<div class="note">${itens.length} abastecimentos selecionados • ${num(qt)} L • ${money(valor)}</div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Número medição</label><input id="mmNum" value="MED-${new Date().getFullYear()}-${String(db.medicoes.length+1).padStart(4,'0')}"></div><div class="field"><label>Posto</label><input value="${postoNome(postos[0])}" disabled></div><div class="field"><label>Período</label><input value="${dateBR(datas[0])} a ${dateBR(datas.at(-1))}" disabled></div><div class="field"><label>Número NF</label><input id="mmNf"></div><div class="field"><label>Série</label><input id="mmSerie"></div><div class="field"><label>Chave DANFE/NF-e</label><input id="mmChave" maxlength="44"></div><div class="field"><label>Quantidade NF (L)</label><input type="number" step="0.01" id="mmQtNf" value="${qt}"></div><div class="field"><label>Valor NF</label><input type="number" step="0.01" id="mmValNf" value="${valor.toFixed(2)}"></div><div class="field"><label>Data emissão</label><input type="date" id="mmEmissao"></div><div class="field"><label>Vencimento</label><input type="date" id="mmVenc"></div><div class="field"><label>DANFE (PDF)</label><input type="file" id="mmDanfe" accept="application/pdf"></div><div class="field"><label>Status</label><select id="mmStatus"><option>Aguardando NF</option><option>Conciliada</option><option>Aprovada</option></select></div></div>`,m=>{let qnf=nval('mmQtNf'),vnf=nval('mmValNf'),diffQ=Math.abs(qnf-qt)/(qt||1)*100,diffV=Math.abs(vnf-valor)/(valor||1)*100,file=$('#mmDanfe').files[0];if(db.config.params.danfeObrigatorio&&!file)return toast('DANFE é obrigatório pela configuração atual');let med={id:uid('M'),numero:val('mmNum'),postoId:postos[0],unidadeIds:unis,produtoIds:prods,inicio:datas[0],fim:datas.at(-1),nf:val('mmNf'),serie:val('mmSerie'),chave:val('mmChave'),qt,valor,qtNf:qnf,valorNf:vnf,emissao:val('mmEmissao'),vencimento:val('mmVenc'),status:(diffQ>db.config.params.tolNF||diffV>db.config.params.tolNF)?'Divergência':val('mmStatus'),danfeNome:file?.name||'',itens:ids};db.medicoes.push(med);db.abastecimentos.forEach(a=>{if(ids.includes(a.id))a.medicaoId=med.id});if(file){let rd=new FileReader();rd.onload=()=>{try{localStorage.setItem('danfe_'+med.id,rd.result)}catch{toast('DANFE grande demais para armazenamento local; metadados foram salvos.')}};rd.readAsDataURL(file)}audit('Criação','Medição',med.numero);save('Medição criada');m.remove();render()})}

function relatorios(){pageTitle('Relatórios','Medições, pendências e preços');let pend=db.abastecimentos.filter(x=>!x.medicaoId),grp={};pend.forEach(a=>{let k=[a.postoId,a.unidadeId,a.produtoId].join('|');if(!grp[k])grp[k]={postoId:a.postoId,unidadeId:a.unidadeId,produtoId:a.produtoId,qt:0,valor:0,min:a.data,max:a.data};let g=grp[k];g.qt+=a.qt;g.valor+=a.total;g.min=a.data<g.min?a.data:g.min;g.max=a.data>g.max?a.data:g.max});$('#view').innerHTML=`<div class="panel"><h2>Medições realizadas</h2><div class="table-wrap"><table><thead><tr><th>Medição</th><th>Posto</th><th>Ciclo</th><th>NF</th><th>Produtos</th><th>Qt</th><th>Valor</th><th>Status</th></tr></thead><tbody>${db.medicoes.map(m=>`<tr><td>${m.numero}</td><td>${postoNome(m.postoId)}</td><td>${dateBR(m.inicio)} a ${dateBR(m.fim)}</td><td>${m.nf||'-'}</td><td>${m.produtoIds.map(produtoNome).join(', ')}</td><td>${num(m.qt)} L</td><td>${money(m.valor)}</td><td>${badge(m.status)}</td></tr>`).join('')||'<tr><td colspan="8">Sem medições.</td></tr>'}</tbody></table></div></div><div class="panel"><h2>Medições pendentes</h2><div class="table-wrap"><table><thead><tr><th>Posto</th><th>Período</th><th>Filial</th><th>Produto</th><th>Qt</th><th>Valor</th></tr></thead><tbody>${Object.values(grp).map(g=>`<tr><td>${postoNome(g.postoId)}</td><td>${dateBR(g.min)} a ${dateBR(g.max)}</td><td>${unidadeNome(g.unidadeId)}</td><td>${produtoNome(g.produtoId)}</td><td>${num(g.qt)} L</td><td>${money(g.valor)}</td></tr>`).join('')||'<tr><td colspan="6">Sem pendências.</td></tr>'}</tbody></table></div></div><div class="panel"><h2>Preço por Posto × PRV × Ticketlog</h2><div class="table-wrap"><table><thead><tr><th>Posto</th><th>Produto</th><th>Preço Posto</th><th>PRV Vixpar</th><th>Ticketlog</th><th>Δ PRV</th><th>Δ Ticketlog</th><th>Impacto mensal x Ticketlog</th></tr></thead><tbody>${db.acordos.map(a=>`<tr><td>${postoNome(a.postoId)}</td><td>${produtoNome(a.produtoId)}</td><td>${money(a.preco)}</td><td>${money(a.prv)}</td><td>${money(a.ticketlog)}</td><td class="${a.preco<=a.prv?'price-good':'price-bad'}">${money(a.preco-a.prv)}</td><td class="${a.preco<=a.ticketlog?'price-good':'price-bad'}">${money(a.preco-a.ticketlog)}</td><td>${money((a.ticketlog-a.preco)*a.volumeMes)}</td></tr>`).join('')}</tbody></table></div></div>`}
function documentos(){pageTitle('Documentos','DANFEs e documentos vinculados');let meds=db.medicoes.filter(x=>x.danfeNome);$('#view').innerHTML=`<div class="panel"><h2>DANFEs anexados</h2><div class="table-wrap"><table><thead><tr><th>Medição</th><th>Posto</th><th>NF</th><th>Arquivo</th><th>Ação</th></tr></thead><tbody>${meds.map(m=>`<tr><td>${m.numero}</td><td>${postoNome(m.postoId)}</td><td>${m.nf}</td><td>${m.danfeNome}</td><td><button class="btn small secondary openDoc" data-id="${m.id}">Abrir</button></td></tr>`).join('')||'<tr><td colspan="5">Nenhum documento anexado.</td></tr>'}</tbody></table></div></div>`;$$('.openDoc').forEach(b=>b.onclick=()=>{let d=localStorage.getItem('danfe_'+b.dataset.id);if(d)window.open(d,'_blank');else toast('Arquivo não disponível neste navegador')})}
function config(){pageTitle('Configurações','Módulos, parâmetros, campos obrigatórios e usuários');let modLabels={dashboard:'Dashboard',postos:'Postos',bases:'Bases Supridoras',distribuidoras:'Distribuidoras',produtos:'Produtos',unidades:'Unidades Vixpar',frota:'Frota',rede:'Rede de Atendimento',acordos:'Acordos & Calculadora',abastecimentos:'Abastecimentos',medicoes:'Medições',relatorios:'Relatórios',documentos:'Gestão Documental',usuarios:'Usuários'};$('#view').innerHTML=`<div class="split"><div><div class="panel"><h2>Módulos do sistema</h2><p class="note">Desativar um módulo apenas oculta sua operação. Os dados históricos permanecem preservados.</p>${Object.entries(modLabels).map(([k,l])=>`<div class="switch-row"><span>${l}</span><div class="switch ${db.config.modules[k]!==false?'on':''}" data-mod="${k}"></div></div>`).join('')}</div><div class="panel"><h2>Campos obrigatórios</h2>${[['postoCnpj','CNPJ do posto'],['postoMunicipio','Município do posto'],['produtoSap','Código SAP do produto'],['frotaCentroCusto','Centro de Custo da frota']].map(([k,l])=>`<div class="switch-row"><span>${l}</span><div class="switch ${db.config.required[k]?'on':''}" data-req="${k}"></div></div>`).join('')}</div></div><div><div class="panel"><h2>Parâmetros</h2><div class="form-grid two">${[['margemPosto','Margem posto padrão (%)'],['taxaAdm','Taxa adm padrão (%)'],['taxaFinanceira','Taxa financeira Vixpar (% a.m.)'],['cicloDirectFuel','Ciclo DirectFuel (dias)'],['cicloTicketlog','Ciclo Ticketlog (dias)'],['pagDirectFuel','Pagamento DirectFuel (dias)'],['pagTicketlog','Pagamento Ticketlog (dias)'],['tolPreco','Tolerância preço (%)'],['tolNF','Tolerância NF (%)']].map(([k,l])=>`<div class="field"><label>${l}</label><input type="number" step="0.01" data-param="${k}" value="${db.config.params[k]}"></div>`).join('')}</div><div class="switch-row"><span>DANFE obrigatório na medição</span><div class="switch ${db.config.params.danfeObrigatorio?'on':''}" data-param-bool="danfeObrigatorio"></div></div><div class="toolbar" style="margin-top:14px"><button class="btn primary" id="saveParams">Salvar parâmetros</button></div></div><div class="panel"><h2>Usuários e acesso</h2><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Unidades</th><th>Status</th></tr></thead><tbody>${db.users.map(u=>`<tr><td>${u.nome}</td><td>${u.email}</td><td>${u.perfil}</td><td>${u.unidades}</td><td>${badge(u.ativo?'Ativo':'Inativo')}</td></tr>`).join('')}</tbody></table></div><p class="note" style="margin-top:12px">O acesso ao site exige login no ChatGPT e e-mail corporativo @vix.com.br.</p></div></div></div>`;$$('[data-mod]').forEach(s=>s.onclick=()=>{let k=s.dataset.mod;db.config.modules[k]=!(db.config.modules[k]!==false);save();render()});$$('[data-req]').forEach(s=>s.onclick=()=>{let k=s.dataset.req;db.config.required[k]=!db.config.required[k];save();render()});$$('[data-param-bool]').forEach(s=>s.onclick=()=>{db.config.params[s.dataset.paramBool]=!db.config.params[s.dataset.paramBool];save();render()});$('#saveParams').onclick=()=>{$$('[data-param]').forEach(i=>db.config.params[i.dataset.param]=Number(i.value)||0);audit('Alteração','Configurações','Parâmetros');save('Parâmetros salvos');render()}}
function auditPage(){pageTitle('Auditoria','Histórico de alterações do sistema');$('#view').innerHTML=`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Data/Hora</th><th>Usuário</th><th>Ação</th><th>Entidade</th><th>Detalhe</th></tr></thead><tbody>${db.audit.map(l=>`<tr><td>${new Date(l.data).toLocaleString('pt-BR')}</td><td>${l.usuario}</td><td>${l.acao}</td><td>${l.entidade}</td><td>${l.detalhe}</td></tr>`).join('')||'<tr><td colspan="5">Sem registros.</td></tr>'}</tbody></table></div></div>`}

$('#btnReset').onclick=()=>{if(confirm('Restaurar os dados de demonstração? Seus dados locais serão substituídos.'))reset()};$('#btnExport').onclick=()=>{let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='directfuel_vixpar_backup_'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href)};$('#fileImport').onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{db=JSON.parse(r.result);save('Backup importado');render()}catch{toast('Arquivo de backup inválido')}};r.readAsText(f)};
setInterval(()=>$('#clock').textContent=new Date().toLocaleString('pt-BR'),1000);$('#clock').textContent=new Date().toLocaleString('pt-BR');save();render();
